// Fisher-Yates Shuffle — Algorithms, route: jsx
// Source: algorithms:shuffle/fisher-yates
//
// Self-contained: every local import is inlined below. Requires only d3, motion, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useEffect, useMemo, useState } from 'react';
import * as d3 from 'd3';
import { motion } from 'motion/react';

// ---- inlined from shuffle ----
/** mulberry32: a fixed seed keeps every shuffle identical across reloads. */
function seededRandom(seed: number): () => number {
  let state = seed;
  return () => {
    state = (state + 0x6d2b79f5) | 0;
    let t = Math.imul(state ^ (state >>> 15), 1 | state);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const random = seededRandom(20260813);

const barCount = 24;

/** `order[position]` is the element currently sitting there; `i` is the settled boundary. */
type ShuffleFrame = { order: number[]; i: number; j: number };

function fisherYatesFrames(count: number): ShuffleFrame[] {
  const order = Array.from({ length: count }, (_, index) => index);
  const frames: ShuffleFrame[] = [{ order: order.slice(), i: count, j: -1 }];

  for (let i = count - 1; i > 0; --i) {
    const j = Math.floor(random() * (i + 1));
    [order[i], order[j]] = [order[j], order[i]];
    frames.push({ order: order.slice(), i, j });
  }

  frames.push({ order: order.slice(), i: 0, j: -1 });
  return frames;
}

const shuffleFrames = fisherYatesFrames(barCount);

const matrixSize = 8;
const trials = 4000;
const expectedCount = trials / matrixSize;

function fisherYatesShuffle(values: number[]): number[] {
  for (let i = values.length - 1; i > 0; --i) {
    const j = Math.floor(random() * (i + 1));
    [values[i], values[j]] = [values[j], values[i]];
  }
  return values;
}

// Insertion sort written out rather than handed to Array.prototype.sort: the standard leaves
// the sorting algorithm to the engine, so the exact bias would not be reproducible.
function comparatorShuffle(values: number[]): number[] {
  for (let k = 1; k < values.length; ++k) {
    const item = values[k];
    let m = k - 1;
    while (m >= 0 && random() - 0.5 > 0) {
      values[m + 1] = values[m];
      --m;
    }
    values[m + 1] = item;
  }
  return values;
}

/** counts[element][position]: how often element i lands at position j over every trial. */
function biasMatrix(shuffle: (values: number[]) => number[]): number[][] {
  const counts = Array.from({ length: matrixSize }, () => new Array<number>(matrixSize).fill(0));
  for (let trial = 0; trial < trials; ++trial) {
    shuffle(Array.from({ length: matrixSize }, (_, index) => index)).forEach((element, position) => {
      counts[element][position] += 1;
    });
  }
  return counts;
}

const fisherYatesMatrix = biasMatrix(fisherYatesShuffle);
const comparatorMatrix = biasMatrix(comparatorShuffle);

const maxCount = Math.max(
  ...fisherYatesMatrix.flat(),
  ...comparatorMatrix.flat()
);

const MARGIN = { top: 34, right: 16, bottom: 34, left: 16 };
const STEP_MS = 420;
const TRANSITION = { duration: 0.28, ease: 'easeInOut' } as const;

export default function FisherYatesShuffle({ width }: { width: number }) {
  const height = Math.round(width * 0.5);
  const innerWidth = Math.max(1, width - MARGIN.left - MARGIN.right);
  const innerHeight = Math.max(1, height - MARGIN.top - MARGIN.bottom);

  // Opens on the finished shuffle so the first painted frame is already the whole story;
  // the effect then rewinds to the identity permutation and replays.
  const [step, setStep] = useState(shuffleFrames.length - 1);

  useEffect(() => {
    setStep(0);
    const id = window.setInterval(() => setStep((s) => (s + 1) % shuffleFrames.length), STEP_MS);
    return () => window.clearInterval(id);
  }, []);

  const frame = shuffleFrames[step];

  const x = useMemo(
    () =>
      d3
        .scaleBand<number>()
        .domain(d3.range(barCount))
        .range([0, innerWidth])
        .padding(0.18),
    [innerWidth]
  );

  const y = useMemo(() => d3.scaleLinear([0, barCount], [innerHeight, 0]), [innerHeight]);

  /** Invert the frame so each element can be looked up by identity, which is what motion keys on. */
  const positionOf = useMemo(() => {
    const positions = new Array<number>(barCount);
    frame.order.forEach((element, index) => {
      positions[element] = index;
    });
    return positions;
  }, [frame]);

  if (width === 0) return null;

  const settledStart = x(frame.i) ?? innerWidth;
  const caretFor = (index: number) => (x(index) ?? 0) + x.bandwidth() / 2;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label={`Fisher-Yates shuffle of ${barCount} elements in progress, with the settled tail of the array shaded`}
      style={{ display: 'block', font: '11px sans-serif' }}
    >
      <text x={MARGIN.left} y={14} fill="var(--muted)">
        Fisher-Yates: swap element i with a uniform pick from 0 to i, then shrink i
      </text>

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {/* Everything from i rightwards is already final; that invariant is the algorithm. */}
        <rect
          x={settledStart}
          y={-8}
          width={Math.max(0, innerWidth - settledStart)}
          height={innerHeight + 8}
          fill="var(--accent)"
          fillOpacity={0.09}
        />
        {frame.i < barCount && (
          <text x={settledStart + 4} y={-12} fill="var(--accent)" fillOpacity={0.9}>
            shuffled and final
          </text>
        )}

        {d3.range(barCount).map((element) => {
          const active = positionOf[element] === frame.i || positionOf[element] === frame.j;
          return (
            <motion.rect
              key={element}
              y={y(element + 1)}
              height={innerHeight - y(element + 1)}
              width={x.bandwidth()}
              fill={d3.interpolateTurbo((element + 0.5) / barCount)}
              fillOpacity={frame.j < 0 || active ? 1 : 0.55}
              animate={{ x: x(positionOf[element]) ?? 0 }}
              transition={TRANSITION}
            />
          );
        })}

        <line x1={0} x2={innerWidth} y1={innerHeight} y2={innerHeight} stroke="var(--line)" />

        {frame.j >= 0 && (
          <g fill="var(--accent)" textAnchor="middle">
            <text x={caretFor(frame.i)} y={innerHeight + 16}>
              {frame.i === frame.j ? 'i = j' : 'i'}
            </text>
            {frame.i !== frame.j && (
              <text x={caretFor(frame.j)} y={innerHeight + 16}>
                j
              </text>
            )}
          </g>
        )}
      </g>
    </svg>
  );
}
